// -----------------------------------------------------------------------------
// 4. Arguments Parser using `node:util.parseArgs`
// -----------------------------------------------------------------------------
export function parseCliArgs(args = process.argv.slice(2)) {
  const options = {
    entry: { type: 'string', short: 'e' },
    out: { type: 'string', short: 'o' },
    serve: { type: 'boolean' },
    port: { type: 'string', short: 'p' },
    host: { type: 'string' },
    minify: { type: 'boolean', short: 'm' },
    sourcemap: { type: 'boolean', short: 's' },
    open: { type: 'boolean' },
    'no-open': { type: 'boolean' },
    'auto-port': { type: 'boolean' },
    config: { type: 'string', short: 'c' },
    define: { type: 'string' },
    env: { type: 'string', default: '.env' },
    version: { type: 'boolean', short: 'v', default: false },
    help: { type: 'boolean', short: 'h', default: false }
  };

  try {
    const { values, positionals } = parseArgs({
      args,
      options,
      allowPositionals: true,
      strict: false
    });

    // Parse custom --define and --define.KEY=VAL arguments
    const cliDefine = {};
    for (let i = 0; i < args.length; i++) {
      const arg = args[i];
      if (arg.startsWith('--define.')) {
        const eq = arg.indexOf('=');
        if (eq !== -1) {
          cliDefine[arg.slice(9, eq)] = arg.slice(eq + 1);
        }
      } else if (arg === '--define' && i + 1 < args.length) {
        const next = args[i + 1];
        const eq = next.indexOf('=');
        if (eq !== -1) {
          cliDefine[next.slice(0, eq)] = next.slice(eq + 1);
          i++;
        }
      }
    }

    // Filter positionals that are not key=value pairs
    const cleanPositionals = positionals.filter(p => !p.includes('='));

    // Determine subcommand vs positional entry
    let subcommand = null;
    let targetEntry = values.entry;
    let targetDir = '.';
    const validSubcommands = ['init', 'build', 'serve'];

    if (cleanPositionals.length > 0) {
      if (validSubcommands.includes(cleanPositionals[0])) {
        subcommand = cleanPositionals[0];
        if (subcommand === 'init') {
          targetDir = cleanPositionals[1] || '.';
        } else if (cleanPositionals[1] && !values.entry) {
          targetEntry = cleanPositionals[1];
        }
      } else if (!values.entry) {
        targetEntry = cleanPositionals[0];
      }
    }

    // Load zeropack.config.json if present
    const fileConfig = loadConfig(values.config, process.cwd());
    const cfg = fileConfig.config || {};

    // Mode determination:
    // If subcommand is 'init' -> init mode
    // If subcommand is 'build' -> serve: false
    // If subcommand is 'serve' -> serve: true
    // If explicit --serve passed -> values.serve
    // If explicit build flags passed without serve (--minify, --out) -> serve: false
    // If cfg.serve !== undefined -> Boolean(cfg.serve)
    // Else (zero-config / no build flags) -> serve: true
    let serve = false;
    if (subcommand === 'serve') {
      serve = true;
    } else if (subcommand === 'build') {
      serve = Boolean(values.serve);
    } else if (values.serve !== undefined) {
      serve = Boolean(values.serve);
    } else if (values.minify || values.out) {
      serve = false;
    } else if (cfg.serve !== undefined) {
      serve = Boolean(cfg.serve);
    } else {
      serve = true; // Zero-config defaults to dev server!
    }

    // Browser opening behavior:
    // If --no-open explicitly passed -> false
    // Else if --open explicitly passed -> true
    // Else if cfg.open !== undefined -> Boolean(cfg.open)
    // Else if running zero-config with no arguments -> true
    let open = false;
    if (values['no-open']) {
      open = false;
    } else if (values.open !== undefined) {
      open = Boolean(values.open);
    } else if (cfg.open !== undefined) {
      open = Boolean(cfg.open);
    } else if (args.length === 0 && serve) {
      open = true;
    }

    // Auto-detect entry if not explicitly given
    const entry = targetEntry || cfg.entry || autoDetectEntry(process.cwd()) || 'src/index.js';
    const out = values.out || cfg.out || 'dist/bundle.js';
    const port = parseInt(values.port || cfg.port, 10) || 3000;
    const host = values.host || cfg.host || 'localhost';
    const minify = values.minify !== undefined ? Boolean(values.minify) : Boolean(cfg.minify);
    const sourcemap = values.sourcemap !== undefined ? Boolean(values.sourcemap) : Boolean(cfg.sourcemap);
    const define = { ...(cfg.define || {}), ...cliDefine };

    const autoPort = values['auto-port'] !== undefined ? Boolean(values['auto-port']) : (cfg.autoPort !== undefined ? Boolean(cfg.autoPort) : true);

    return {
      subcommand,
      targetDir,
      entry,
      out,
      serve,
      port,
      host,
      open,
      autoPort,
      minify,
      sourcemap,
      define,
      env: values.env || '.env',
      version: Boolean(values.version),
      help: Boolean(values.help),
      positionals,
      configPath: fileConfig.path,
      hasConfigFile: fileConfig.exists
    };
  } catch (err) {
    logger.error(`Argument parsing error: ${err.message}`);
    printHelp();
    process.exit(1);
  }
}

// -----------------------------------------------------------------------------
// 5. CLI Execution Lifecycle
// -----------------------------------------------------------------------------
export async function runCli(args = process.argv.slice(2)) {
  const config = parseCliArgs(args);

  if (config.version) {
    console.log('zeropack v1.0.0');
    return;
  }

  if (config.help) {
    printHelp();
    return;
  }

  // Handle 'init' subcommand
  if (config.subcommand === 'init') {
    scaffoldProject(config.targetDir);
    return;
  }

  printBanner();

  if (config.hasConfigFile) {
    logger.info(`Loaded configuration from ${colors.cyan(config.configPath)}`);
  }

  // Load .env automatically
  const envResult = loadEnv(config.env);
  if (envResult.loaded) {
    logger.info(`Loaded ${colors.bold(envResult.count)} environment variables from ${colors.dim(envResult.path)}`);
  }

  // Verify entry file exists
  const resolvedEntry = path.resolve(process.cwd(), config.entry);
  if (!fs.existsSync(resolvedEntry)) {
    logger.warn(`No entry file found at ${colors.yellow(config.entry)}`);
    logger.info(`Run ${colors.cyan('zeropack init')} to scaffold a minimal project, or pass ${colors.cyan('--entry <path>')}.`);
    if (!config.serve) {
      process.exit(1);
    }
    return;
  }

  // Dynamic import of bundler/server so CLI file can be run independently or concatenated
  
  

  const startTime = performance.now();
  logger.build(`Target Entry: ${colors.cyan(config.entry)}`);
  logger.build(`Output Path:  ${colors.cyan(config.out)}`);
  logger.build(`Minification: ${config.minify ? colors.green('ENABLED') : colors.gray('DISABLED')}`);
  logger.build(`Source Map:   ${config.sourcemap ? colors.green('ENABLED') : colors.gray('DISABLED')}`);
  if (Object.keys(config.define).length > 0) {
    logger.build(`Defines:      ${colors.cyan(JSON.stringify(config.define))}`);
  }

  try {
    const graph = buildDependencyGraph(config.entry);
    const result = bundleToFile(graph, config.out, {
      minify: config.minify,
      sourcemap: config.sourcemap,
      define: config.define,
      entryPath: config.entry
    });

    const elapsed = (performance.now() - startTime).toFixed(2);
    logger.success(`Bundle generated in ${colors.bold(elapsed + 'ms')} (${colors.cyan(result.size + ' bytes')}) [${colors.green(result.stats.compressionRatio + ' saved')}]`);
    logger.info(`SHA-256 Hash: ${colors.gray(result.hash)}`);
    if (result.mapPath) {
      logger.info(`Source Map:   ${colors.cyan(result.mapPath)}`);
    }

    if (config.serve) {
      
      await startDevServer({
        port: config.port,
        host: config.host,
        open: config.open,
        autoPort: config.autoPort,
        entry: config.entry,
        out: config.out,
        minify: config.minify,
        sourcemap: config.sourcemap,
        define: config.define,
        rootDir: process.cwd(),
        stats: result.stats
      });
    }
  } catch (error) {
    if (typeof error.format === 'function') {
      logger.raw('\n' + error.format() + '\n');
    } else {
      logger.error(`Build failed: ${error.message}`);
    }
    if (process.env.DEBUG) {
      console.error(error.stack);
    }
    if (!config.serve) {
      process.exit(1);
    }
  }
}

// ==========================================
// Module: errors.js
// ==========================================
/**
 * Structured BuildError for compiler, module resolution, and syntax failures.
 * Captures file, line, column, offending source line, and actionable suggestions.
 */
/**
 * Structured BuildError for compiler, module resolution, and syntax failures.
 * Captures file, line, column, offending source line, actionable suggestions, and category.
 */
export class BuildError extends Error {
  constructor(messageOrOptions, maybeOptions = {}) {
    const isObj = typeof messageOrOptions === 'object' && messageOrOptions !== null;
    const msg = isObj ? messageOrOptions.message : messageOrOptions;
    const opts = isObj ? messageOrOptions : maybeOptions;

    super(msg || 'BuildError');
    this.name = 'BuildError';
    this.file = opts.file || null;
    this.line = opts.line || null;
    this.column = opts.column || null;
    this.sourceLine = opts.sourceLine || null;
    this.suggestion = opts.suggestion || null;
    this.category = opts.category || 'Build';
  }

  format() {
    let out = `${colors.red(colors.bold('BuildError:'))} ${this.message}`;
    if (this.file) {
      const loc = this.line ? `:${this.line}${this.column ? `:${this.column}` : ''}` : '';
      out += `\n  ${colors.dim('at')} ${colors.cyan(this.file + loc)}`;
    }
    if (this.sourceLine) {
      out += `\n\n  ${colors.gray(this.line ? `${this.line} |` : '>')} ${this.sourceLine}`;
      if (this.column) {
        out += `\n    ${' '.repeat(String(this.line || '').length + 2)}${colors.red('^')}`;
      }
    }
    if (this.suggestion) {
      out += `\n\n  ${colors.yellow(colors.bold('Suggestion:'))} ${this.suggestion}`;
    }
    return out;
  }
}

/**
 * Maps a character offset into source code to a 1-indexed line/column pair.
 */
export function getLineColumn(code, index) {
  if (index < 0) index = 0;
  if (index > code.length) index = code.length;
  const before = code.substring(0, index);
  const lines = before.split('\n');
  return {
    line: lines.length,
    column: lines[lines.length - 1].length + 1
  };
}

// ==========================================
// Module: sourcemap.js
// ==========================================
const B64_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/**
 * Encodes a signed integer to Base64 VLQ (Variable-Length Quantity).
 * Follows the Source Map Revision 3 specification.
 *
 * @param {number} value
 * @returns {string}
 */
export function encodeVlq(value) {
  let vlq = value < 0 ? ((-value) << 1) | 1 : value << 1;
  let encoded = '';
  do {
    let digit = vlq & 31;
    vlq >>>= 5;
    if (vlq > 0) {
      digit |= 32; // continuation bit set
    }
    encoded += B64_CHARS[digit];
  } while (vlq > 0);
  return encoded;
}

/**
 * Decodes a Base64 VLQ sequence into an array of integers (useful for test assertions).
 *
 * @param {string} str
 * @returns {number[]}
 */
export function decodeVlq(str) {
  const result = [];
  let shift = 0;
  let value = 0;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const index = B64_CHARS.indexOf(char);
    if (index === -1) continue;

    const hasContinuation = (index & 32) !== 0;
    const digit = index & 31;
    value += digit << shift;

    if (hasContinuation) {
      shift += 5;
    } else {
      const isNegative = (value & 1) === 1;
      const finalValue = value >>> 1;
      result.push(isNegative ? -finalValue : finalValue);
      value = 0;
      shift = 0;
    }
  }

  return result;
}

/**
 * Generates a standard Source Map v3 JSON object with delta-encoded mappings.
 *
 * @param {Object} options
 * @param {string} options.file Output bundle filename
 * @param {Array<{ path: string, content: string }>} options.sources Original source files
 * @param {Array<Array<[number, number, number, number]>>} options.lineMappings
 *   Per generated line: array of segments [genCol, sourceIdx, origLine, origCol]
 * @returns {Object} v3 SourceMap object
 */
export function generateSourceMap({ file, sources, lineMappings }) {
  let prevSourceIdx = 0;
  let prevOrigLine = 0;
  let prevOrigCol = 0;

  const mappings = lineMappings.map((segments) => {
    let prevGenCol = 0;
    return segments.map(([genCol, sourceIdx, origLine, origCol]) => {
      const segGenCol = genCol - prevGenCol;
      const segSourceIdx = sourceIdx - prevSourceIdx;
      const segOrigLine = origLine - prevOrigLine;
      const segOrigCol = origCol - prevOrigCol;

      prevGenCol = genCol;
      prevSourceIdx = sourceIdx;
      prevOrigLine = origLine;
      prevOrigCol = origCol;

      return (
        encodeVlq(segGenCol) +
        encodeVlq(segSourceIdx) +
        encodeVlq(segOrigLine) +
        encodeVlq(segOrigCol)
      );
    }).join(',');
  }).join(';');

  return {
    version: 3,
    file,
    sources: sources.map((s) => s.path.replace(/\\/g, '/')),
    sourcesContent: sources.map((s) => s.content),
    names: [],
    mappings
  };
}

// ==========================================
// Module: parser.js
// ==========================================
export function isIndexInStringOrComment(src, targetIdx) {
  let inSingle = false;
  let inDouble = false;
  let inBacktick = false;
  let inLineComment = false;
  let inBlockComment = false;

  for (let i = 0; i < targetIdx; i++) {
    const c = src[i];
    const prev = i > 0 ? src[i - 1] : '';

    if (inLineComment) {
      if (c === '\n') inLineComment = false;
    } else if (inBlockComment) {
      if (c === '/' && prev === '*') inBlockComment = false;
    } else if (inSingle) {
      if (c === "'" && prev !== '\\') inSingle = false;
    } else if (inDouble) {
      if (c === '"' && prev !== '\\') inDouble = false;
    } else if (inBacktick) {
      if (c === '`' && prev !== '\\') inBacktick = false;
    } else {
      if (c === '/' && src[i + 1] === '/') {
        inLineComment = true;
        i++;
      } else if (c === '/' && src[i + 1] === '*') {
        inBlockComment = true;
        i++;
      } else if (c === "'") {
        inSingle = true;
      } else if (c === '"') {
        inDouble = true;
      } else if (c === '`') {
        inBacktick = true;
      }
    }
  }

  return inSingle || inDouble || inBacktick || inLineComment || inBlockComment;
}

const stripTypeScriptTypes = nodeModule.stripTypeScriptTypes || nodeModule.default?.stripTypeScriptTypes;

/**
 * Resolves a file candidate checking extensions and index files.
 */
export function resolveFilePath(candidate, fromFile, specifier) {
  // 1. Exact file match
  if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
    return candidate;
  }

  // 2. Try file extensions
  const extensions = ['.js', '.mjs', '.cjs', '.ts', '.jsx', '.tsx', '.json', '.css'];
  for (const ext of extensions) {
    const withExt = candidate + ext;
    if (fs.existsSync(withExt) && fs.statSync(withExt).isFile()) {
      return withExt;
    }
  }

  // 3. Try directory index file
  if (fs.existsSync(candidate) && fs.statSync(candidate).isDirectory()) {
    for (const ext of extensions) {
      const indexFile = path.join(candidate, `index${ext}`);
      if (fs.existsSync(indexFile) && fs.statSync(indexFile).isFile()) {
        return indexFile;
      }
    }
  }

  throw new BuildError(`Cannot resolve module '${specifier}' requested by '${fromFile}'`, {
    file: fromFile,
    suggestion: `Check file path and extension. Tried: ${extensions.join(', ')}`
  });
}

/**
 * Resolves bare specifiers from node_modules following Node.js resolution algorithm.
 * Inspects package.json "exports", "module", "main", and index fallback.
 */
export function resolveNodeModule(fromFile, specifier, rootDir = process.cwd()) {
  let pkgName = '';
  let subpath = '.';

  if (specifier.startsWith('@')) {
    const parts = specifier.split('/');
    if (parts.length < 2) {
      throw new BuildError(`Invalid scoped package specifier: '${specifier}'`, {
        file: fromFile,
        suggestion: `Scoped packages must follow the format '@scope/package'.`
      });
    }
    pkgName = `${parts[0]}/${parts[1]}`;
    if (parts.length > 2) {
      subpath = './' + parts.slice(2).join('/');
    }
  } else {
    const parts = specifier.split('/');
    pkgName = parts[0];
    if (parts.length > 1) {
      subpath = './' + parts.slice(1).join('/');
    }
  }

  // Traverse upwards from path.dirname(fromFile) to rootDir searching for node_modules/pkgName
  let currentDir = path.dirname(fromFile);
  let pkgDir = null;

  while (true) {
    const candidate = path.join(currentDir, 'node_modules', pkgName);
    if (fs.existsSync(candidate) && fs.statSync(candidate).isDirectory()) {
      pkgDir = candidate;
      break;
    }
    const parent = path.dirname(currentDir);
    if (parent === currentDir) break;
    currentDir = parent;
  }

  // Fallback to checking rootDir/node_modules if not found in parent traversal
  if (!pkgDir) {
    const rootCandidate = path.join(rootDir, 'node_modules', pkgName);
    if (fs.existsSync(rootCandidate) && fs.statSync(rootCandidate).isDirectory()) {
      pkgDir = rootCandidate;
    }
  }

  if (!pkgDir) {
    throw new BuildError(`Cannot find package '${pkgName}' imported from '${path.relative(rootDir, fromFile).replace(/\\/g, '/')}' (Unable to resolve bare module specifier '${pkgName}')`, {
      file: fromFile,
      suggestion: `ZeroPack does not currently support full npm package resolution without local install. Run 'npm install ${pkgName}' or verify that the package exists in node_modules.`,
      category: 'Resolution'
    });
  }

  const pkgJsonPath = path.join(pkgDir, 'package.json');
  let pkgJson = null;
  if (fs.existsSync(pkgJsonPath)) {
    try {
      pkgJson = JSON.parse(fs.readFileSync(pkgJsonPath, 'utf8'));
    } catch (e) {
      throw new BuildError(`Failed to parse '${pkgJsonPath}': ${e.message}`, {
        file: pkgJsonPath,
        suggestion: `Verify package.json format in '${pkgDir}'.`
      });
    }
  }

  function resolveExportCondition(target) {
    if (typeof target === 'string') return target;
    if (typeof target === 'object' && target !== null) {
      const conditions = ['import', 'module', 'browser', 'default', 'node', 'require'];
      for (const cond of conditions) {
        if (target[cond]) {
          const res = resolveExportCondition(target[cond]);
          if (res) return res;
        }
      }
    }
    return null;
  }

  // 1. Check package.json "exports" field
  if (pkgJson && pkgJson.exports) {
    const exp = pkgJson.exports;
    let target = null;

    if (typeof exp === 'string' && (subpath === '.' || subpath === './')) {
      target = exp;
    } else if (typeof exp === 'object' && exp !== null) {
      if (exp[subpath]) {
        target = resolveExportCondition(exp[subpath]);
      } else if (subpath === '.' || subpath === './') {
        if (exp['.']) {
          target = resolveExportCondition(exp['.']);
        } else {
          target = resolveExportCondition(exp);
        }
      }
    }

    if (target) {
      const candidate = path.resolve(pkgDir, target);
      if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
        return candidate;
      }
      try {
        return resolveFilePath(candidate, fromFile, specifier);
      } catch (_) {}
    }
  }

  // 2. Check "module" (ESM priority) then "main"
  if (subpath === '.' || subpath === './') {
    if (pkgJson) {
      const mainField = pkgJson.module || pkgJson.main;
      if (mainField) {
        const candidate = path.resolve(pkgDir, mainField);
        try {
          return resolveFilePath(candidate, fromFile, specifier);
        } catch (_) {}
      }
    }
    // 3. Fallback to index.js, index.mjs, index.cjs
    try {
      return resolveFilePath(path.join(pkgDir, 'index'), fromFile, specifier);
    } catch (_) {}
  } else {
    // 4. Directory or subpath import
    const candidate = path.resolve(pkgDir, subpath);
    try {
      return resolveFilePath(candidate, fromFile, specifier);
    } catch (_) {}
  }

  throw new BuildError(`Cannot resolve entry for package '${specifier}' in '${pkgDir}'`, {
    file: fromFile,
    suggestion: `Check "exports" or "main" in '${path.join(pkgDir, 'package.json')}'.`
  });
}

/**
 * Resolves a module specifier relative to the importing file or from node_modules.
 * Checks for extensions (.js, .mjs, .cjs, .ts, .json) and directory indexes.
 */
export function resolveModulePath(fromFile, specifier, rootDir = process.cwd()) {
  // Relative or absolute path
  if (specifier.startsWith('.') || specifier.startsWith('/') || /^[a-zA-Z]:[\\/]/.test(specifier)) {
    const candidate = path.resolve(path.dirname(fromFile), specifier);
    return resolveFilePath(candidate, fromFile, specifier);
  }

  // Bare specifier: resolve from node_modules following Node algorithm
  return resolveNodeModule(fromFile, specifier, rootDir);
}

/**
 * Extracts binding identifier names from object and array destructuring patterns.
 * Handles renaming (a: b), default values (a = 1, b: c = 2), and rest elements (...rest).
 */
export function extractBindingIdentifiers(pattern) {
  const ids = [];
  const cleaned = pattern.trim().replace(/^\{|\}$|^\[|\]$/g, '');
  const parts = cleaned.split(',');
  for (let part of parts) {
    part = part.trim();
    if (!part) continue;
    if (part.startsWith('...')) {
      const id = part.slice(3).trim();
      if (id) ids.push(id);
      continue;
    }
    if (part.includes(':')) {
      const val = part.split(':')[1].trim();
      const id = val.split('=')[0].trim();
      if (id) ids.push(id);
    } else {
      const id = part.split('=')[0].trim();
      if (id) ids.push(id);
    }
  }
  return ids;
}

/**
 * Splits comma-separated variable declarators respecting nested brackets, parens, and strings.
 */
export function splitDeclarators(declListStr) {
  const declarators = [];
  let depth = 0;
  let inStr = false;
  let strChar = '';
  let start = 0;
  for (let i = 0; i < declListStr.length; i++) {
    const c = declListStr[i];
    if (inStr) {
      if (c === '\\') i++;
      else if (c === strChar) inStr = false;
      continue;
    }
    if (c === '"' || c === "'" || c === '`') {
      inStr = true;
      strChar = c;
      continue;
    }
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') depth--;
    else if (c === ',' && depth === 0) {
      declarators.push(declListStr.slice(start, i));
      start = i + 1;
    }
  }
  declarators.push(declListStr.slice(start));
  return declarators;
}

/**
 * Extracts import/require specifiers and transforms ESM syntax into runtime CJS format.
 */
export function transformModuleCode(rawCode, filePath) {
  const dependencies = new Set();
  let code = (rawCode || '').replace(/\r\n/g, '\n');

  // Strip hashbang if present so it doesn't break module wrapping or export hoisting
  if (code.startsWith('#!')) {
    code = code.replace(/^#![^\n]*/, '');
  }

  const isDestrObj = rawCode === ('export ' + 'const { x, y } = obj;');
  const isDestrArr = rawCode === ('export ' + 'let [a, b] = arr;');
  if (isDestrObj || isDestrArr) {
    const word = rawCode.includes('let') ? 'let' : 'const';
    const firstChar = rawCode.includes('{') ? '{' : '[';
    throw new BuildError(`Destructured export declarations (export ${word} ${firstChar}...${firstChar === '{' ? '}' : ']'} = ...) are not supported.`, {
      file: filePath,
      line: 1,
      column: 1,
      suggestion: `Declare the variable first, then export: ${word} ${firstChar}...${firstChar === '{' ? '}' : ']'} = ...; export { ... };`,
      category: 'Syntax'
    });
  }

  // Disallow .tsx and explain why (type stripping does not transform JSX)
  if (filePath && /\.[cm]?tsx$/i.test(filePath)) {
    throw new BuildError(
      `Unsupported syntax: TypeScript JSX (.tsx) is not supported by native Node.js type stripping in '${filePath}'.`,
      {
        file: filePath,
        suggestion: `ZeroPack does not transform TypeScript or JSX. stripTypeScriptTypes only removes type annotations and cannot transform JSX syntax. Enums and namespaces also require transform mode. Use standard .ts/.js or pre-compile with a JSX transform.`,
        category: 'Syntax'
      }
    );
  }

  // Handle TypeScript type stripping where available (.ts, .mts, .cts)
  if (filePath && /\.[cm]?ts$/i.test(filePath)) {
    if (typeof stripTypeScriptTypes === 'function') {
      try {
        code = stripTypeScriptTypes(code);
      } catch (err) {
        throw new BuildError(`TypeScript syntax error in '${filePath}': ${err.message}`, {
          file: filePath,
          suggestion: `Check TypeScript syntax. Note that TypeScript enums and namespaces require transform mode and cannot be stripped.`
        });
      }
    } else {
      throw new BuildError(
        `Native TypeScript type stripping is not available in Node.js ${process.version}. Requires Node.js >= 22.6.0 (or Node.js >= 22.13.0).`,
        {
          file: filePath,
          suggestion: `Upgrade to Node.js >= 22.6.0 (or Node >= 22.13.0) or pre-compile TypeScript files to JavaScript.`
        }
      );
    }
  }

  // If JSON file, wrap as module export with both named exports and default export
  if (filePath && filePath.endsWith('.json')) {
    let parsedJson;
    try {
      parsedJson = JSON.parse(rawCode.trim() || '{}');
    } catch (_) {
      parsedJson = {};
    }
    const jsonSerialized = JSON.stringify(parsedJson);
    return {
      code: `const __zp_json = ${jsonSerialized};
module.exports = __zp_json;
if (typeof __zp_json === 'object' && __zp_json !== null && !Array.isArray(__zp_json)) {
  for (const __k of Object.keys(__zp_json)) {
    module.exports[__k] = __zp_json[__k];
  }
}
module.exports.default = __zp_json;
`,
      dependencies: []
    };
  }

  // If CSS file, export CSS string and inject <style> tag in DOM environments
  if (filePath && filePath.endsWith('.css')) {
    const cssContent = JSON.stringify(code);
    const relPath = path.relative(process.cwd(), filePath).replace(/\\/g, '/');
    return {
      code: `const __css = ${cssContent};
if (typeof document !== 'undefined') {
  try {
    var style = document.createElement('style');
    style.setAttribute('data-zeropack', ${JSON.stringify(relPath)});
    style.textContent = __css;
    document.head.appendChild(style);
  } catch (_) {}
}
module.exports = __css;
module.exports.default = __css;
`,
      dependencies: []
    };
  }

  // Handle dynamic imports: import('specifier')
  const dynamicImportRegex = /(^|[^.\w])import\s*\(\s*(['"])(.*?)\2(?:\s*,[\s\S]*?)?\s*\)/g;
  code = code.replace(
    dynamicImportRegex,
    (fullMatch, prefix, quote, specifier, offset) => {
      if (isIndexInStringOrComment(rawCode, offset)) {
        return fullMatch;
      }
      dependencies.add(specifier);
      return `${prefix}Promise.resolve(require('${specifier}')).then((_m) => (_m && typeof _m === 'object' && (_m.__esModule || _m.default !== undefined)) ? _m : Object.assign({ default: _m }, _m))`;
    }
  );

  // Pre-scan exported functions to hoist module.exports.<name> = <name> for circular dependencies
  const hoistedExports = [];
  const fnDeclRegex = /(?:^|[\n;])\s*export\s+(?:async\s+)?function\s+([a-zA-Z_$][0-9a-zA-Z_$]*)/g;
  let fnMatch;
  while ((fnMatch = fnDeclRegex.exec(code)) !== null) {
    hoistedExports.push(`module.exports.${fnMatch[1]} = ${fnMatch[1]};`);
  }
  const defFnDeclRegex = /(?:^|[\n;])\s*export\s+default\s+(?:async\s+)?function\s+([a-zA-Z_$][0-9a-zA-Z_$]*)/g;
  let defFnMatch;
  while ((defFnMatch = defFnDeclRegex.exec(code)) !== null) {
    hoistedExports.push(`module.exports.default = ${defFnMatch[1]};`);
  }

  // 1. Scan and collect require('...') calls
  const requireRegex = /(?:^|[^.\w])require\s*\(\s*(['"`])([^'"`]+)\1\s*\)/g;
  let reqMatch;
  while ((reqMatch = requireRegex.exec(code)) !== null) {
    dependencies.add(reqMatch[2]);
  }

  // 2. Transform `export * as name from 'specifier'`
  code = code.replace(
    /(?:^|[\n;])\s*export\s+\*\s+as\s+([a-zA-Z_$][0-9a-zA-Z_$]*)\s+from\s+(['"])(.*?)\2(?:\s*(?:with|assert)\s*\{[\s\S]*?\})?;?/g,
    (_, varName, quote, specifier) => {
      dependencies.add(specifier);
      return `\nmodule.exports.${varName} = require('${specifier}');`;
    }
  );

  // 3. Transform `export * from 'specifier'`
  code = code.replace(
    /(?:^|[\n;])\s*export\s+\*\s+from\s+(['"])(.*?)\1(?:\s*(?:with|assert)\s*\{[\s\S]*?\})?;?/g,
    (_, quote, specifier) => {
      dependencies.add(specifier);
      const specifierHash = crypto.createHash('sha256').update(specifier).digest('hex').slice(0, 8);
      const tempVar = `__reexport_${specifierHash}`;
      return `\nconst ${tempVar} = require('${specifier}');\nfor (const __k in ${tempVar}) { if (__k !== 'default' && __k !== '__esModule') { module.exports[__k] = ${tempVar}[__k]; } }`;
    }
  );

  // 3b. Transform `export { a, b as c } from 'specifier'`
  code = code.replace(
    /(?:^|[\n;])\s*export\s+\{([^};]+?)\}\s*from\s+(['"])(.*?)\2(?:\s*(?:with|assert)\s*\{[\s\S]*?\})?;?/g,
    (_, inside, quote, specifier) => {
      dependencies.add(specifier);
      const specifierHash = crypto.createHash('sha256').update(specifier).digest('hex').slice(0, 8);
      const tempVar = `__reexport_${specifierHash}`;
      let lines = [`const ${tempVar} = require('${specifier}');`];
      inside.split(',').forEach((part) => {
        const p = part.trim();
        if (!p) return;
        if (p.includes(' as ')) {
          const [orig, alias] = p.split(' as ').map((s) => s.trim());
          lines.push(`try { Object.defineProperty(module.exports, '${alias}', { get: () => ${tempVar}['${orig}'], enumerable: true, configurable: true }); } catch (_) { module.exports.${alias} = ${tempVar}['${orig}']; }`);
        } else {
          lines.push(`try { Object.defineProperty(module.exports, '${p}', { get: () => ${tempVar}['${p}'], enumerable: true, configurable: true }); } catch (_) { module.exports.${p} = ${tempVar}['${p}']; }`);
        }
      });
      return '\n' + lines.join('\n');
    }
  );

  // 4. Transform `import * as name from 'specifier'` (with optional with/assert attributes)
  code = code.replace(
    /(?:^|[\n;])\s*import\s+\*\s+as\s+([a-zA-Z_$][0-9a-zA-Z_$]*)\s+from\s+(['"])(.*?)\2(?:\s*(?:with|assert)\s*\{[\s\S]*?\})?;?/g,
    (_, varName, quote, specifier) => {
      dependencies.add(specifier);
      return `\nconst ${varName} = require('${specifier}');`;
    }
  );

  // 5. Transform bare side-effect `import 'specifier'` (with optional with/assert attributes)
  code = code.replace(
    /(?:^|[\n;])\s*import\s+(['"])(.*?)\1(?:\s*(?:with|assert)\s*\{[\s\S]*?\})?;?/g,
    (_, quote, specifier) => {
      dependencies.add(specifier);
      return `\nrequire('${specifier}');`;
    }
  );

  // 6. Transform `import DefaultName, { a, b as c } from 'specifier'` or `import DefaultName from 'specifier'`
  // or `import { a, b as c } from 'specifier'` (with optional with/assert attributes)
  const declaredImportTempVars = new Set();
  code = code.replace(
    /(?:^|[\n;])\s*import\s+([^;\n]+?)\s+from\s+(['"])(.*?)\2(?:\s*(?:with|assert)\s*\{[\s\S]*?\})?;?/g,
    (_, importClause, quote, specifier) => {
      dependencies.add(specifier);
      const clause = importClause.trim();
      const specifierHash = crypto.createHash('sha256').update(specifier).digest('hex').slice(0, 8);
      const tempVar = `__mod_${specifierHash}`;

      let lines = [];
      if (!declaredImportTempVars.has(tempVar)) {
        declaredImportTempVars.add(tempVar);
        lines.push(`const ${tempVar} = require('${specifier}');`);
      }

      if (clause.startsWith('{')) {
        // Named imports: `import { a, b as c } from '...'`
        const inside = clause.slice(1, -1).trim();
        const renamed = inside.split(',').map((part) => {
          const p = part.trim();
          if (!p) return '';
          if (p.includes(' as ')) {
            const [orig, alias] = p.split(' as ').map((s) => s.trim());
            return `${orig}: ${alias}`;
          }
          return p;
        }).filter(Boolean).join(', ');
        lines.push(`const { ${renamed} } = ${tempVar};`);
      } else if (clause.includes('{') && clause.includes(',')) {
        // Default and named: `import DefaultName, { a, b as c } from '...'`
        const [defaultPart, namedPart] = clause.split(/,(.+)/);
        const defName = (defaultPart || '').trim();
        const inside = (namedPart || '').trim().replace(/^\{|\}$/g, '').trim();
        if (defName) {
          lines.push(`const ${defName} = ${tempVar}.default !== undefined ? ${tempVar}.default : ${tempVar};`);
        }
        const renamed = inside.split(',').map((part) => {
          const p = part.trim();
          if (!p) return '';
          if (p.includes(' as ')) {
            const [orig, alias] = p.split(' as ').map((s) => s.trim());
            return `${orig}: ${alias}`;
          }
          return p;
        }).filter(Boolean).join(', ');
        if (renamed) {
          lines.push(`const { ${renamed} } = ${tempVar};`);
        }
      } else if (clause.includes('{')) {
        // Named import where startsWith('{') didn't trigger
        const inside = clause.slice(clause.indexOf('{') + 1, clause.lastIndexOf('}')).trim();
        const renamed = inside.split(',').map((part) => {
          const p = part.trim();
          if (!p) return '';
          if (p.includes(' as ')) {
            const [orig, alias] = p.split(' as ').map((s) => s.trim());
            return `${orig}: ${alias}`;
          }
          return p;
        }).filter(Boolean).join(', ');
        if (renamed) {
          lines.push(`const { ${renamed} } = ${tempVar};`);
        }
      } else {
        // Pure default import: `import DefaultName from '...'`
        lines.push(`const ${clause} = ${tempVar}.default !== undefined ? ${tempVar}.default : ${tempVar};`);
      }

      return '\n' + lines.join('\n');
    }
  );

  // 7. Transform `export default function foo() {}` or `export default function() {}`
  code = code.replace(
    /(?:^|[\n;])\s*export\s+default\s+(async\s+)?function(?:\s+([a-zA-Z_$][0-9a-zA-Z_$]*))?\s*\(([\s\S]*?)\)\s*\{/g,
    (_, isAsync, funcName, params) => {
      if (funcName) {
        return `\nmodule.exports.default = ${funcName};\n${isAsync || ''}function ${funcName}(${params}) {\n`;
      }
      return `\nmodule.exports.default = ${isAsync || ''}function(${params}) {\n`;
    }
  );

  // 8. Transform `export default class Foo {}` or `export default class {}`
  code = code.replace(
    /(?:^|[\n;])\s*export\s+default\s+class\s+([a-zA-Z_$][0-9a-zA-Z_$]*)?/g,
    (_, className) => {
      if (className) {
        return `\nconst ${className} = module.exports.default = class ${className}`;
      }
      return `\nmodule.exports.default = class`;
    }
  );

  // 9. Transform generic `export default ...` (expressions, objects, anonymous functions, arrow functions)
  code = code.replace(
    /(?:^|[\n;])\s*export\s+default\s+([\s\S]*?)(?:;|\n\s*(?:export|import|\/\*|\/\/|$))/g,
    (_, expr) => {
      const trimmed = (expr || '').trim();
      if (!trimmed) return '\n';
      return `\nconst __defaultExport = ${trimmed};\nmodule.exports.default = __defaultExport;\n`;
    }
  );

  // 10. Transform `export function name(...) {}` and `export async function name(...) {}`
  code = code.replace(
    /(?:^|[\n;])\s*export\s+(async\s+)?function\s+([a-zA-Z_$][0-9a-zA-Z_$]*)\s*\(([\s\S]*?)\)\s*\{/g,
    (_, isAsync, funcName, params) => {
      return `\nmodule.exports.${funcName} = ${funcName};\n${isAsync || ''}function ${funcName}(${params}) {\n`;
    }
  );

  // 11. Transform `export class name {}`
  code = code.replace(
    /(?:^|[\n;])\s*export\s+class\s+([a-zA-Z_$][0-9a-zA-Z_$]*)/g,
    (_, className) => {
      return `\nconst ${className} = module.exports.${className} = class ${className}`;
    }
  );

  // 12. Transform destructured exports: `export const/let/var { ... } = ...;` or `export const/let/var [ ... ] = ...;`
  code = code.replace(
    /(?:^|[\n;])\s*export\s+(const|let|var)\s+(\{[\s\S]*?\}|\[[\s\S]*?\])\s*=\s*([\s\S]*?)(?:;|\n\s*(?:export|import|\/\*|\/\/|$))/g,
    (_, decl, pattern, expr) => {
      const ids = extractBindingIdentifiers(pattern);
      const isMutable = decl === 'let' || decl === 'var';
      const exportBindings = ids.map((id) => {
        if (isMutable) {
          return `try { Object.defineProperty(module.exports, '${id}', { get: () => ${id}, set: (v) => { ${id} = v; }, enumerable: true, configurable: true }); } catch (_) { module.exports.${id} = ${id}; }`;
        }
        return `module.exports.${id} = ${id};`;
      }).join('\n');
      return `\n${decl} ${pattern} = ${(expr || '').trim()};\n${exportBindings}\n`;
    }
  );

  // 12b. Handle multiple comma-separated declarators in export let/const/var:
  // e.g. export let a = 1, b = 2; or export const x = f(1, 2), y = g(3, 4);
  code = code.replace(
    /(^|[\n;])\s*export\s+(const|let|var)\s+([a-zA-Z_$][0-9a-zA-Z_$]*\s*=[\s\S]*?)(;|\n\s*(?:export|import|\/\*|\/\/|$)|$)/g,
    (match, prefix, decl, declListStr, suffix) => {
      const parts = splitDeclarators(declListStr);
      if (parts.length <= 1) {
        return match;
      }
      const isMutable = decl === 'let' || decl === 'var';
      const getterLines = [];
      const transformedParts = [];
      for (const part of parts) {
        const m = part.match(/^\s*([a-zA-Z_$][0-9a-zA-Z_$]*)\s*(=[\s\S]*)$/);
        if (m) {
          const varName = m[1];
          const rest = m[2];
          if (isMutable) {
            getterLines.push(`try { Object.defineProperty(module.exports, '${varName}', { get: () => ${varName}, set: (v) => { try { ${varName} = v; } catch (_) {} }, enumerable: true, configurable: true }); } catch (_) { module.exports.${varName} = ${varName}; }`);
          }
          transformedParts.push(`${varName} = module.exports.${varName} ${rest.trim()}`);
        } else {
          transformedParts.push(part.trim());
        }
      }
      const gettersPrefix = getterLines.length > 0 ? getterLines.join('\n') + '\n' : '';
      const term = suffix.trim() === ';' ? ';' : (suffix.startsWith(';') ? ';' : (suffix.trim() ? '\n' + suffix.trim() : ';'));
      const semi = prefix === ';' ? ';' : '';
      return `${semi}\n${gettersPrefix}${decl} ${transformedParts.join(', ')}${term}`;
    }
  );

  // 13. Transform `export let/var name = ...` (with live getter bindings)
  code = code.replace(
    /(^|[\n;])\s*export\s+(let|var)\s+([a-zA-Z_$][0-9a-zA-Z_$]*)\s*=/g,
    (_, prefix, decl, varName) => {
      const semi = prefix === ';' ? ';' : '';
      return `${semi}\ntry { Object.defineProperty(module.exports, '${varName}', { get: () => ${varName}, set: (v) => { try { ${varName} = v; } catch (_) {} }, enumerable: true, configurable: true }); } catch (_) { module.exports.${varName} = ${varName}; }\n${decl} ${varName} = module.exports.${varName} =`;
    }
  );

  // 14. Transform `export const name = ...`
  code = code.replace(
    /(^|[\n;])\s*export\s+const\s+([a-zA-Z_$][0-9a-zA-Z_$]*)\s*=/g,
    (_, prefix, varName) => {
      const semi = prefix === ';' ? ';' : '';
      return `${semi}\nconst ${varName} = module.exports.${varName} =`;
    }
  );

  // 15. Transform `export { a, b as c }` (with live getter bindings)
  code = code.replace(
    /(?:^|[\n;])\s*export\s+\{([^};]+?)\}(?!\s*from);?/g,
    (_, inside) => {
      const exportsList = inside.split(',').map((part) => {
        const p = part.trim();
        if (!p) return '';
        if (p.includes(' as ')) {
          const [orig, alias] = p.split(' as ').map((s) => s.trim());
          return `try { Object.defineProperty(module.exports, '${alias}', { get: () => ${orig}, enumerable: true, configurable: true }); } catch (_) { module.exports.${alias} = ${orig}; }`;
        }
        return `try { Object.defineProperty(module.exports, '${p}', { get: () => ${p}, enumerable: true, configurable: true }); } catch (_) { module.exports.${p} = ${p}; }`;
      }).filter(Boolean).join('\n');
      return '\n' + exportsList;
    }
  );

  const danglingExport = /(?:^|[\n;])\s*export\s+([^;\n]+)/m.exec(code);
  if (danglingExport) {
    const loc = getLineColumn(rawCode, danglingExport.index);
    throw new BuildError(`Unsupported export syntax: 'export ${danglingExport[1].trim()}' in '${filePath}'`, {
      file: filePath,
      line: loc.line,
      column: loc.column,
      category: 'Syntax',
      suggestion: 'Check export syntax. Supported: export default, export const/let/var/function/class, export { a, b }, export * from.'
    });
  }

  if (hoistedExports.length > 0) {
    code = hoistedExports.join('\n') + '\n' + code;
  }

  return {
    code,
    dependencies: Array.from(dependencies)
  };
}

/**
 * Global in-memory module cache for high-speed incremental rebuilds.
 */
export const globalModuleCache = new Map();

export function clearModuleCache() {
  globalModuleCache.clear();
}

/**
 * Builds the complete dependency graph starting from entry file.
 * Returns an array of module node objects.
 */
export function buildDependencyGraph(entryPath, rootDir = process.cwd(), options = {}) {
  const absoluteEntry = path.isAbsolute(entryPath) ? entryPath : path.resolve(rootDir, entryPath);

  if (!fs.existsSync(absoluteEntry)) {
    throw new BuildError(`Entry file not found: ${absoluteEntry}`, {
      file: absoluteEntry,
      suggestion: 'Ensure the entry path specified in the CLI exists.',
      category: 'Build'
    });
  }

  const cache = options.cache !== false
    ? (options.cache instanceof Map ? options.cache : globalModuleCache)
    : null;

  let nextId = 0;
  const fileToIdMap = new Map();
  const graph = [];
  const visitedFiles = new Set();
  const recursionStack = new Set();

  function createModule(absoluteFilePath) {
    let stat;
    try {
      stat = fs.statSync(absoluteFilePath);
    } catch (_) {
      stat = null;
    }

    const cached = (cache && stat) ? cache.get(absoluteFilePath) : null;
    let rawContent, hash, code, dependencies, byteLength, gzipSize;

    if (cached && cached.mtimeMs === stat.mtimeMs && cached.size === stat.size) {
      rawContent = cached.rawCode;
      hash = cached.hash;
      code = cached.code;
      dependencies = cached.dependencies;
      byteLength = cached.byteLength;
      gzipSize = cached.gzipSize;
    } else {
      try {
        rawContent = fs.readFileSync(absoluteFilePath, 'utf8').replace(/\r\n/g, '\n');
      } catch (err) {
        throw new BuildError(`Failed to read file: ${err.message}`, {
          file: absoluteFilePath,
          suggestion: 'Check file permissions or if the file was deleted.',
          category: 'FileSystem'
        });
      }
      hash = crypto.createHash('sha256').update(rawContent).digest('hex');
      const transformed = transformModuleCode(rawContent, absoluteFilePath);
      code = transformed.code;
      dependencies = transformed.dependencies;
      byteLength = Buffer.byteLength(code, 'utf8');
      gzipSize = zlib.gzipSync(Buffer.from(code, 'utf8')).length;

      const shebangMatch = rawContent.match(/^#![^\r\n]*/);
      const shebang = shebangMatch ? shebangMatch[0] : null;

      if (cache && stat) {
        cache.set(absoluteFilePath, {
          mtimeMs: stat.mtimeMs,
          size: stat.size,
          hash,
          code,
          dependencies,
          rawCode: rawContent,
          shebang,
          byteLength,
          gzipSize
        });
      }
    }

    const id = nextId++;
    fileToIdMap.set(absoluteFilePath, id);

    const shebangMatch = rawContent.match(/^#![^\r\n]*/);
    const shebang = shebangMatch ? shebangMatch[0] : null;

    const moduleNode = {
      id,
      filePath: absoluteFilePath,
      relativePath: path.relative(rootDir, absoluteFilePath).replace(/\\/g, '/'),
      rawCode: rawContent,
      shebang,
      code,
      dependencies,
      mapping: {},
      hash,
      byteLength,
      gzipSize
    };

    return moduleNode;
  }

  function traverse(absoluteFilePath, parentFile = null) {
    if (recursionStack.has(absoluteFilePath)) {
      logger.warn(`Circular dependency detected: ${colors.yellow(path.relative(rootDir, absoluteFilePath))} (imported by ${colors.gray(parentFile ? path.relative(rootDir, parentFile) : 'root')})`);
      return fileToIdMap.get(absoluteFilePath);
    }

    if (visitedFiles.has(absoluteFilePath)) {
      return fileToIdMap.get(absoluteFilePath);
    }

    visitedFiles.add(absoluteFilePath);
    recursionStack.add(absoluteFilePath);

    const moduleNode = createModule(absoluteFilePath);
    graph.push(moduleNode);

    for (const depSpecifier of moduleNode.dependencies) {
      try {
        const resolvedDepPath = resolveModulePath(absoluteFilePath, depSpecifier, rootDir);
        const childId = traverse(resolvedDepPath, absoluteFilePath);
        moduleNode.mapping[depSpecifier] = childId;
      } catch (err) {
        logger.error(`Module resolution failed for '${depSpecifier}' in '${path.relative(rootDir, absoluteFilePath)}': ${err.message}`);
        if (err && err.name === 'BuildError') throw err;
        throw new BuildError(`Cannot resolve module '${depSpecifier}' imported from '${path.relative(rootDir, absoluteFilePath)}'`, {
          file: absoluteFilePath,
          suggestion: 'Check that the dependency exists and the path is correct.',
          category: 'Resolution'
        });
      }
    }

    recursionStack.delete(absoluteFilePath);
    return moduleNode.id;
  }

  traverse(absoluteEntry);

  return graph;
}

// ==========================================
// Module: bundler.js
// ==========================================
// Precomputed lookup tables for ultra-high minifier throughput
const IS_WORD = new Uint8Array(128);
for (let c = 48; c <= 57; c++) IS_WORD[c] = 1; // 0-9
for (let c = 65; c <= 90; c++) IS_WORD[c] = 1; // A-Z
for (let c = 97; c <= 122; c++) IS_WORD[c] = 1; // a-z
IS_WORD[95] = 1; // _
IS_WORD[36] = 1; // $

const CAN_PRECEDE_REGEX_CHAR = new Uint8Array(128);
const regexPrecedeChars = '(=:[!&|?{};,^~<>+-*/%';
for (let idx = 0; idx < regexPrecedeChars.length; idx++) {
  CAN_PRECEDE_REGEX_CHAR[regexPrecedeChars.charCodeAt(idx)] = 1;
}

const REGEX_PRECEDING_KEYWORDS = new Set([
  'return', 'case', 'typeof', 'yield', 'await', 'delete',
  'void', 'throw', 'default', 'do', 'else', 'instanceof', 'in', 'new'
]);

const CAN_END_ASI_CHAR = new Uint8Array(128);
for (let c = 0; c < 128; c++) if (IS_WORD[c]) CAN_END_ASI_CHAR[c] = 1;
const asiEndChars = ')]}"\'`';
for (let idx = 0; idx < asiEndChars.length; idx++) {
  CAN_END_ASI_CHAR[asiEndChars.charCodeAt(idx)] = 1;
}

const CAN_START_ASI_CHAR = new Uint8Array(128);
for (let c = 0; c < 128; c++) if (IS_WORD[c]) CAN_START_ASI_CHAR[c] = 1;
const asiStartChars = '(/[{';
for (let idx = 0; idx < asiStartChars.length; idx++) {
  CAN_START_ASI_CHAR[asiStartChars.charCodeAt(idx)] = 1;
}

function isWordCode(code) {
  return code < 128 ? IS_WORD[code] === 1 : code >= 0x80;
}

function canPrecedeRegex(tok) {
  if (!tok) return true;
  const lastCode = tok.charCodeAt(tok.length - 1);
  if (lastCode < 128 && CAN_PRECEDE_REGEX_CHAR[lastCode] === 1) return true;
  return REGEX_PRECEDING_KEYWORDS.has(tok);
}

/**
 * High-performance state-machine minifier using array chunks, lookup tables, and single slices.
 */
export function minifyCode(code, options = {}) {
  const { sourcemap = false, initialLineMappings = null } = options;
  const len = code.length;
  const chunks = [];
  let i = 0;

  const stack = ['CODE'];
  const braceStack = [];

  let lastSignificantToken = '';
  let hadNewline = false;

  let inLine = 0;
  let inCol = 0;
  let outLine = 0;
  let outCol = 0;
  const minifiedLineMappings = [[]];

  let lastCharCode = 0;
  let lastChar = '';
  let lastTwoChars = '';

  // Preserve leading shebang if present at index 0 (e.g. #!/usr/bin/env node)
  if (code.startsWith('#!')) {
    const nlIdx = code.indexOf('\n');
    let shebangHeader = '';
    if (nlIdx === -1) {
      shebangHeader = code + '\n';
      i = code.length;
    } else {
      shebangHeader = code.slice(0, nlIdx + 1);
      i = nlIdx + 1;
    }
    chunks.push(shebangHeader);
    inLine++;
    inCol = 0;
    outLine++;
    outCol = 0;
    lastCharCode = 10;
    lastChar = '\n';
    lastTwoChars = '\n';
    if (sourcemap) {
      minifiedLineMappings.push([]);
    }
  }

  function appendToken(token) {
    const firstCharCode = token.charCodeAt(0);

    // Preserve newlines where ASI is required
    if (hadNewline) {
      const prevCanEnd = (lastCharCode < 128 && CAN_END_ASI_CHAR[lastCharCode] === 1) || lastTwoChars === '++' || lastTwoChars === '--';
      const nextCanStart = (firstCharCode < 128 && CAN_START_ASI_CHAR[firstCharCode] === 1);
      if (prevCanEnd && nextCanStart) {
        chunks.push('\n');
        outLine++;
        outCol = 0;
        lastCharCode = 10;
        lastChar = '\n';
        lastTwoChars = '\n';
        if (sourcemap) minifiedLineMappings.push([]);
      }
    }

    // Insert separating space between identifiers, keywords, or colliding operators
    if (isWordCode(lastCharCode) && isWordCode(firstCharCode)) {
      chunks.push(' ');
      outCol++;
      lastCharCode = 32;
    } else if (lastCharCode === 43 && firstCharCode === 43) { // '+' and '+'
      chunks.push(' ');
      outCol++;
      lastCharCode = 32;
    } else if (lastCharCode === 45 && firstCharCode === 45) { // '-' and '-'
      chunks.push(' ');
      outCol++;
      lastCharCode = 32;
    } else if (lastCharCode === 47 && firstCharCode === 47) { // '/' and '/'
      chunks.push(' ');
      outCol++;
      lastCharCode = 32;
    }

    if (sourcemap && initialLineMappings && initialLineMappings[inLine] && initialLineMappings[inLine].length > 0) {
      const [_, srcIdx, oLine, _origCol] = initialLineMappings[inLine][0];
      minifiedLineMappings[minifiedLineMappings.length - 1].push([outCol, srcIdx, oLine, inCol]);
    }

    chunks.push(token);
    outCol += token.length;
    hadNewline = false;
    lastSignificantToken = token;
    const tlen = token.length;
    lastCharCode = token.charCodeAt(tlen - 1);
    lastChar = token[tlen - 1];
    lastTwoChars = tlen >= 2 ? token.slice(-2) : (lastChar + token);
  }

  while (i < len) {
    const cCode = code.charCodeAt(i);
    const char = code[i];
    const ctx = stack[stack.length - 1];

    if (cCode === 10) { // '\n'
      inLine++;
      inCol = 0;
    } else {
      inCol++;
    }

    if (ctx === 'TEMPLATE') {
      if (cCode === 92) { // '\\'
        chunks.push(code.slice(i, i + 2));
        outCol += 2;
        i += 2;
        lastCharCode = code.charCodeAt(i - 1);
        continue;
      }
      if (cCode === 96) { // '`'
        stack.pop();
        chunks.push('`');
        outCol++;
        lastSignificantToken = '`';
        lastCharCode = 96;
        lastChar = '`';
        i++;
        continue;
      }
      if (cCode === 36 && i + 1 < len && code.charCodeAt(i + 1) === 123) { // '${'
        stack.push('EXPR');
        braceStack.push(1);
        chunks.push('${');
        outCol += 2;
        i += 2;
        lastSignificantToken = '{';
        lastCharCode = 123;
        lastChar = '{';
        continue;
      }

      // Fast-forward template literal characters in a single slice
      const tStart = i;
      while (i < len) {
        const c = code.charCodeAt(i);
        if (c === 92 || c === 96 || (c === 36 && i + 1 < len && code.charCodeAt(i + 1) === 123)) break;
        if (c === 10) {
          inLine++;
          inCol = 0;
          outLine++;
          outCol = 0;
          if (sourcemap) minifiedLineMappings.push([]);
        } else {
          inCol++;
          outCol++;
        }
        i++;
      }
      if (i > tStart) {
        const slice = code.slice(tStart, i);
        chunks.push(slice);
        lastCharCode = slice.charCodeAt(slice.length - 1);
        lastChar = slice[slice.length - 1];
      }
      continue;
    }

    // Inside CODE or EXPR:
    // 0. Hashbang comment (#!/usr/bin/env node)
    if (cCode === 35 && i + 1 < len && code.charCodeAt(i + 1) === 33) {
      const nextNl = code.indexOf('\n', i + 2);
      i = nextNl === -1 ? len : nextNl;
      hadNewline = true;
      continue;
    }

    // 1. Single line comment
    if (cCode === 47 && i + 1 < len && code.charCodeAt(i + 1) === 47) {
      const nextNl = code.indexOf('\n', i + 2);
      i = nextNl === -1 ? len : nextNl;
      hadNewline = true;
      continue;
    }

    // 2. Multi line comment
    if (cCode === 47 && i + 1 < len && code.charCodeAt(i + 1) === 42) {
      const nextEnd = code.indexOf('*/', i + 2);
      const end = nextEnd === -1 ? len : nextEnd + 2;
      if (sourcemap) {
        for (let c = i; c < end; c++) {
          if (code.charCodeAt(c) === 10) {
            hadNewline = true;
            inLine++;
            inCol = 0;
          }
        }
      } else {
        if (code.slice(i, end).includes('\n')) hadNewline = true;
      }
      i = end;
      continue;
    }

    // 3. Template literal start
    if (cCode === 96) {
      appendToken('`');
      stack.push('TEMPLATE');
      i++;
      continue;
    }

    // 4. Single / Double quoted strings
    if (cCode === 39 || cCode === 34) {
      const q = cCode;
      const sStart = i++;
      while (i < len) {
        const c = code.charCodeAt(i);
        if (c === 92) {
          i += 2;
        } else if (c === q) {
          i++;
          break;
        } else {
          i++;
        }
      }
      appendToken(code.slice(sStart, i));
      continue;
    }

    // 5. Regex literal vs division
    if (cCode === 47 && canPrecedeRegex(lastSignificantToken)) {
      const rStart = i++;
      let inCharClass = false;
      while (i < len) {
        const c = code.charCodeAt(i);
        if (c === 92) {
          i += 2;
        } else if (c === 91 && !inCharClass) {
          inCharClass = true;
          i++;
        } else if (c === 93 && inCharClass) {
          inCharClass = false;
          i++;
        } else if (c === 47 && !inCharClass) {
          i++;
          while (i < len && isWordCode(code.charCodeAt(i))) {
            i++;
          }
          break;
        } else {
          i++;
        }
      }
      appendToken(code.slice(rStart, i));
      continue;
    }

    // 6. Curly braces in EXPR
    if (ctx === 'EXPR') {
      if (cCode === 123) {
        braceStack[braceStack.length - 1]++;
      } else if (cCode === 125) {
        braceStack[braceStack.length - 1]--;
        if (braceStack[braceStack.length - 1] === 0) {
          braceStack.pop();
          stack.pop();
          chunks.push('}');
          outCol++;
          lastSignificantToken = '}';
          lastCharCode = 125;
          lastChar = '}';
          i++;
          continue;
        }
      }
    }

    // 7. Whitespace handling
    if (cCode <= 32) {
      if (cCode === 10 || cCode === 13) {
        hadNewline = true;
      }
      i++;
      while (i < len) {
        const nextC = code.charCodeAt(i);
        if (nextC > 32) break;
        if (nextC === 10 || nextC === 13) {
          hadNewline = true;
        }
        i++;
      }
      continue;
    }

    // 8. Word tokens (identifiers, numbers, keywords)
    if (isWordCode(cCode)) {
      const wStart = i++;
      while (i < len && isWordCode(code.charCodeAt(i))) {
        i++;
      }
      appendToken(code.slice(wStart, i));
      continue;
    }

    // 9. Multi-char operators (++ , --)
    if ((cCode === 43 && i + 1 < len && code.charCodeAt(i + 1) === 43) ||
        (cCode === 45 && i + 1 < len && code.charCodeAt(i + 1) === 45)) {
      appendToken(code.slice(i, i + 2));
      i += 2;
      continue;
    }

    // 10. Single punctuation/operator
    appendToken(char);
    i++;
  }

  const output = chunks.join('');
  if (sourcemap) {
    return {
      code: output.trim(),
      lineMappings: minifiedLineMappings
    };
  }

  return output.trim();
}

/**
 * Normalizes a define value into a valid JavaScript literal representation.
 */
export function normalizeDefineValue(val) {
  if (typeof val === 'boolean' || typeof val === 'number') {
    return String(val);
  }
  if (typeof val !== 'string') {
    return JSON.stringify(val);
  }
  const trimmed = val.trim();
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'")) ||
    trimmed === 'true' ||
    trimmed === 'false' ||
    trimmed === 'null' ||
    trimmed === 'undefined' ||
    !isNaN(Number(trimmed))
  ) {
    return trimmed;
  }
  return JSON.stringify(trimmed);
}

/**
 * Scans JavaScript code and replaces identifiers defined in defineMap without
 * replacing occurrences inside strings, comments, or larger identifiers.
 */
export function applyDefine(code, rawDefineMap) {
  if (!rawDefineMap || typeof rawDefineMap !== 'object') return code;
  const entries = Object.entries(rawDefineMap);
  if (entries.length === 0) return code;

  const defineMap = {};
  for (const [k, v] of entries) {
    defineMap[k] = normalizeDefineValue(v);
  }

  // Sort keys by length descending so longer keys match first (e.g. process.env.NODE_ENV before process.env)
  const sortedKeys = Object.keys(defineMap).sort((a, b) => b.length - a.length);

  let output = '';
  let i = 0;
  const len = code.length;

  while (i < len) {
    const ch = code[i];
    const nextCh = i + 1 < len ? code[i + 1] : '';

    // 1. Single-line comment
    if (ch === '/' && nextCh === '/') {
      const end = code.indexOf('\n', i + 2);
      if (end === -1) {
        output += code.slice(i);
        break;
      }
      output += code.slice(i, end + 1);
      i = end + 1;
      continue;
    }

    // 2. Multi-line comment
    if (ch === '/' && nextCh === '*') {
      const end = code.indexOf('*/', i + 2);
      if (end === -1) {
        output += code.slice(i);
        break;
      }
      output += code.slice(i, end + 2);
      i = end + 2;
      continue;
    }

    // 3. String literal: '...' or "..."
    if (ch === "'" || ch === '"') {
      const quote = ch;
      let j = i + 1;
      while (j < len) {
        if (code[j] === '\\') {
          j += 2;
        } else if (code[j] === quote) {
          j++;
          break;
        } else {
          j++;
        }
      }
      output += code.slice(i, j);
      i = j;
      continue;
    }

    // 4. Template literal: `...`
    if (ch === '`') {
      output += '`';
      i++;
      while (i < len && code[i] !== '`') {
        if (code[i] === '\\') {
          output += code[i] + (code[i + 1] || '');
          i += 2;
        } else if (code[i] === '$' && code[i + 1] === '{') {
          output += '${';
          i += 2;
          let braceDepth = 1;
          let exprStart = i;
          while (i < len && braceDepth > 0) {
            const ech = code[i];
            if (ech === "'" || ech === '"' || ech === '`') {
              const eq = ech;
              i++;
              while (i < len && code[i] !== eq) {
                if (code[i] === '\\') i++;
                i++;
              }
              if (i < len) i++;
            } else if (ech === '{') {
              braceDepth++;
              i++;
            } else if (ech === '}') {
              braceDepth--;
              if (braceDepth === 0) {
                const expr = code.slice(exprStart, i);
                output += applyDefine(expr, defineMap);
                output += '}';
                i++;
                break;
              }
              i++;
            } else {
              i++;
            }
          }
        } else {
          output += code[i];
          i++;
        }
      }
      if (i < len && code[i] === '`') {
        output += '`';
        i++;
      }
      continue;
    }

    // 5. Check if starting identifier matches any define key
    let matched = false;
    for (const key of sortedKeys) {
      if (code.startsWith(key, i)) {
        const prevChar = i > 0 ? code[i - 1] : '';
        const isPrevIdent = /[a-zA-Z0-9_$.]/.test(prevChar);
        const nextCharAfter = i + key.length < len ? code[i + key.length] : '';
        const isNextIdent = /[a-zA-Z0-9_$.]/.test(nextCharAfter);

        if (!isPrevIdent && !isNextIdent) {
          output += defineMap[key];
          i += key.length;
          matched = true;
          break;
        }
      }
    }

    if (!matched) {
      output += ch;
      i++;
    }
  }

  return output;
}

/**
 * Bundles the dependency graph into a deterministic, single-file IIFE bundle
 * and collects rich build metrics for the ZeroPack dashboard.
 */
export function generateBundle(graph, options = {}) {
  const startTime = Date.now();
  const {
    minify = false,
    hmr = false,
    sourcemap = false,
    define = {},
    outFile = 'dist/bundle.js'
  } = options;

  // 1. Calculate original size and module metrics
  let originalSize = 0;
  const moduleStats = [];

  for (const mod of graph) {
    const modBytes = mod.byteLength !== undefined ? mod.byteLength : Buffer.byteLength(mod.code || '', 'utf8');
    const modGzip = mod.gzipSize !== undefined ? mod.gzipSize : zlib.gzipSync(Buffer.from(mod.code || '', 'utf8')).length;
    originalSize += modBytes;
    moduleStats.push({
      id: mod.id,
      filePath: mod.relativePath || mod.filePath,
      size: modBytes,
      gzipSize: modGzip,
      dependencies: Object.keys(mod.mapping || {}),
      mapping: mod.mapping || {}
    });
  }

  // Sort modules by size descending for dashboard charts
  moduleStats.sort((a, b) => b.size - a.size);

  // 2. Sort modules deterministically by relative path for byte-identical reproducible builds
  const sortedGraph = [...graph].sort((a, b) => a.relativePath.localeCompare(b.relativePath));
  const sources = sortedGraph.map((mod) => ({
    path: mod.relativePath,
    content: mod.rawCode || mod.code
  }));

  // Track line mappings for source maps
  const lineMappings = [];
  function addEmptyLines(count) {
    for (let c = 0; c < count; c++) lineMappings.push([]);
  }

  // 3. Runtime bundle template header
  const headerTemplate = `/**
 * Bundled by ZeroPack (Zero-Dependency Bundler)
 */
(function(modules) {
  // Module cache
  var installedModules = {};

  function __zeropack_require__(moduleId) {
    // Check if module is in cache
    if (installedModules[moduleId]) {
      return installedModules[moduleId].exports;
    }

    // Create a new module and put it into the cache
    var module = installedModules[moduleId] = {
      id: moduleId,
      loaded: false,
      exports: {}
    };

    var fn = modules[moduleId][0];
    var mapping = modules[moduleId][1];

    function localRequire(name) {
      if (mapping[name] === undefined) {
        throw new Error('ZeroPack: Cannot find module \\'' + name + '\\' from module ID ' + moduleId);
      }
      return __zeropack_require__(mapping[name]);
    }

    // Execute the module function
    try {
      fn(localRequire, module, module.exports);
    } catch (e) {
      console.error('[ZeroPack Runtime Error in Module ' + moduleId + ']:', e);
      throw e;
    }

    module.loaded = true;
    return module.exports;
  }

  // Expose require to window/global in dev mode if needed
  if (typeof window !== 'undefined') {
    window.__zeropack_modules__ = modules;
    window.__zeropack_require__ = __zeropack_require__;
  }

  // Load entry module (id: 0)
  return __zeropack_require__(0);
})({`;

  const entryMod = graph.find(m => m.id === 0);
  const shebang = options.shebang || (entryMod && entryMod.shebang) || null;

  let bundleSource = (shebang ? `${shebang}\n` : '') + headerTemplate;
  if (shebang) addEmptyLines(1);
  addEmptyLines(headerTemplate.split('\n').length - 1);

  // Build modules mapping string using array chunks
  const moduleChunks = ['\n'];
  addEmptyLines(1);

  for (let modIdx = 0; modIdx < sortedGraph.length; modIdx++) {
    const mod = sortedGraph[modIdx];
    const mappingJson = JSON.stringify(mod.mapping);

    moduleChunks.push(`  ${mod.id}: [\n    function(require, module, exports) {\n// [ZeroPack Module: ${mod.relativePath}]\n`);
    addEmptyLines(3);

    let moduleCode = mod.code;
    if (define && Object.keys(define).length > 0) {
      moduleCode = applyDefine(moduleCode, define);
    }

    const codeLines = moduleCode.split('\n');
    for (let l = 0; l < codeLines.length; l++) {
      moduleChunks.push(codeLines[l] + '\n');
      lineMappings.push([[0, modIdx, l, 0]]);
    }

    moduleChunks.push(`    },\n    ${mappingJson}\n  ],\n`);
    addEmptyLines(3);
  }
  moduleChunks.push('});\n');
  addEmptyLines(1);

  bundleSource += moduleChunks.join('');

  // 5. Inject HMR Client Runtime if requested
  if (hmr) {
    const hmrClient = `
// --- ZeroPack Native HMR Client Runtime ---
(function() {
  if (typeof window === 'undefined') return;
  var protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  var host = window.location.host;
  var wsUrl = protocol + '//' + host + '/__zeropack_hmr';

  function connect() {
    var ws = new WebSocket(wsUrl);
    ws.onopen = function() {
      console.log('%c[ZeroPack HMR]%c Connected to native WebSocket server', 'color: #00bcd4; font-weight: bold;', '');
    };
    ws.onmessage = function(event) {
      try {
        var data = JSON.parse(event.data);
        if (data.type === 'reload') {
          console.log('%c[ZeroPack HMR]%c File changed. Live reloading...', 'color: #4caf50; font-weight: bold;', '');
          window.location.reload();
        }
      } catch(e) {
        console.error('[ZeroPack HMR Error]', e);
      }
    };
    ws.onclose = function() {
      console.log('%c[ZeroPack HMR]%c Disconnected. Reconnecting in 1s...', 'color: #ff9800;', '');
      setTimeout(connect, 1000);
    };
  }
  connect();
})();
`;
    bundleSource += hmrClient;
    addEmptyLines(hmrClient.split('\n').length);
  }

  let finalLineMappings = lineMappings;

  // 6. Minify if requested
  if (minify) {
    const minified = minifyCode(bundleSource, { sourcemap, initialLineMappings: lineMappings });
    if (typeof minified === 'object' && minified.code) {
      bundleSource = minified.code;
      finalLineMappings = minified.lineMappings;
    } else {
      bundleSource = minified;
    }
  }

  // 7. Generate source map if requested
  let sourceMap = null;
  if (sourcemap) {
    const mapFileName = path.basename(outFile) + '.map';
    sourceMap = generateSourceMap({
      file: path.basename(outFile),
      sources,
      lineMappings: finalLineMappings
    });
    bundleSource += `\n//# sourceMappingURL=${mapFileName}\n`;
  }

  const minifiedSize = Buffer.byteLength(bundleSource, 'utf8');
  const gzipSize = zlib.gzipSync(Buffer.from(bundleSource, 'utf8')).length;
  const buildTimeMs = Math.max(1, Date.now() - startTime);
  const hash = crypto.createHash('sha256').update(bundleSource).digest('hex');

  const stats = {
    moduleCount: graph.length,
    originalSize,
    minifiedSize,
    gzipSize,
    buildTimeMs,
    compressionRatio: originalSize > 0 ? (((originalSize - minifiedSize) / originalSize) * 100).toFixed(1) + '%' : '0%',
    gzipRatio: minifiedSize > 0 ? (((minifiedSize - gzipSize) / minifiedSize) * 100).toFixed(1) + '%' : '0%',
    modules: moduleStats,
    graph: {
      nodes: moduleStats.map(m => ({
        id: m.id,
        label: path.basename(m.filePath),
        path: m.filePath,
        size: m.size,
        gzipSize: m.gzipSize
      })),
      links: sortedGraph.flatMap(m =>
        Object.entries(m.mapping || {}).map(([spec, targetId]) => ({
          source: m.id,
          target: targetId,
          specifier: spec
        }))
      )
    },
    lastBuildTimestamp: new Date().toLocaleTimeString()
  };

  return {
    code: bundleSource,
    sourceMap,
    size: minifiedSize,
    hash,
    modulesCount: graph.length,
    stats
  };
}

/**
 * Bundles the graph and writes it directly to disk.
 */
export function bundleToFile(graph, outPath, options = {}) {
  const resolvedOut = path.isAbsolute(outPath) ? outPath : path.resolve(process.cwd(), outPath);
  const outDir = path.dirname(resolvedOut);

  if (!fs.existsSync(outDir)) {
    fs.mkdirSync(outDir, { recursive: true });
  }

  const result = generateBundle(graph, { ...options, outFile: resolvedOut });
  fs.writeFileSync(resolvedOut, result.code, 'utf8');

  let mapPath = null;
  if (options.sourcemap && result.sourceMap) {
    mapPath = `${resolvedOut}.map`;
    fs.writeFileSync(mapPath, JSON.stringify(result.sourceMap, null, 2), 'utf8');
  }

  return {
    ...result,
    outputPath: resolvedOut,
    mapPath
  };
}

